</style></head><body><?php include '../../includes/menu_secretaria.php';?><main><section class="topo"><h1>Mensagens</h1></section><section class="panel"><?php echo $mensagem;?><h2>Nova mensagem</h2><form method="POST"><label class="label">Destinatário</label><input id="busca-destinatario" class="input" placeholder="Digite o nome ou a turma" autocomplete="off"><div id="resultados" class="resultados"></div><input type="hidden" name="tipo_destino" id="tipo_destino"><input type="hidden" name="destinatario" id="destinatario"><div id="selecionado" style="margin-top:8px;color:#0d4a8f;font-weight:bold"></div><label class="label">Assunto</label><input class="input" name="assunto" required><label class="label">Mensagem</label><textarea class="textarea" name="conteudo" required></textarea><button class="btn" name="enviar_msg" value="1">Enviar mensagem</button></form></section><section class="panel"><h2>Caixa de entrada</h2><?php if($mensagens):?><table><thead><tr><th>Remetente</th><th>Assunto</th><th>Data</th><th>Situação</th></tr></thead><tbody><?php foreach($mensagens as $msg):?><tr class="<?php echo $msg['lida']?'':'nao-lida';?>"><td><?php echo htmlspecialchars($msg['remetente_nome']);?></td><td><a class="assunto" href="?visualizar=1&id_msg=<?php echo $msg['id_mensagem'];?>"><?php echo htmlspecialchars($msg['assunto']??'Sem assunto');?></a></td><td><?php echo (new DateTime($msg['data_envio']))->format('d/m/Y');?></td><td><span class="badge <?php echo $msg['lida']?'lida':'nova';?>"><?php echo $msg['lida']?'Lida':'Não lida';?></span></td></tr><?php endforeach;?></tbody></table><?php else:?><p style="color:#666">Nenhuma mensagem na caixa de entrada.</p><?php endif;?></section></main><script>
const destinatarios=<?php echo json_encode($destinatarios,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP);?>;const busca=document.getElementById('busca-destinatario'),lista=document.getElementById('resultados');function render(){const termo=busca.value.toLocaleLowerCase('pt-BR').trim();lista.innerHTML='';if(!termo)return;destinatarios.filter(item=>item.rotulo.toLocaleLowerCase('pt-BR').includes(termo)).slice(0,30).forEach(item=>{const botao=document.createElement('button');botao.type='button';botao.className='resultado';botao.textContent=item.rotulo;botao.onclick=()=>{document.getElementById('tipo_destino').value=item.tipo;document.getElementById('destinatario').value=item.id;document.getElementById('selecionado').textContent='Selecionado: '+item.rotulo;busca.value=item.rotulo;lista.innerHTML='';};lista.appendChild(botao);});}busca.addEventListener('input',render);
</script></body></html>
